mapper.select:
SELECT a.`id`, a.`business_key`, a.`business_code`, a.`business_type`, a.`meeting_person_document_number`, a.`meeting_person_document_type`, a.`meeting_person_document_type_name`, a.`meeting_person_id`, a.`meeting_person_code`, a.`meeting_person_name`, a.`meeting_person_type`, a.`meeting_person_type_name` FROM `meeting_apply_person` a WHERE a.`deleted` = 0
and a.`business_key` = #{param.businessKey}
and a.`business_type` = #{param.businessType}
and a.`meeting_person_type` = #{param.meetingPersonType}
and `business_key` in
#{item}
ORDER BY a.`meeting_person_type`,a.`create_time` DESC
